int main() {
    int a, b, c;
    if (scanf("%d %d %d", &a, &b, &c) == 3) {
        int max = (a > b) ? ((a > c) ? a : c) : ((b > c) ? b : c);
        printf("%d\n", max);
    }
    return 0;
}

